-- House ads: KChat promoting its own features (they fill slots when no paid campaign wins).
-- Run after 20261029000000_ads.sql. Safe to re-run: skips if house ads already exist.
insert into public.ad_campaigns
  (advertiser_name, advertiser_avatar_url, headline, body, media_url, media_type, width, height, placeholder, cta_label, cta_url, is_house, status, weight, frequency_hours, why_text)
select * from (values
  ('KChat', 'https://api.kiongozi.org/ads-media/kchat-icon.png', 'Your city, live.', 'Your city, live. Stories, friends and what’s on tonight, from the people you actually know.', 'https://api.kiongozi.org/ads-media/ad_city.jpg', 'image', 1080, 1350, 'data:image/jpeg;base64,', 'Invite your crew', 'kchat://invite', true, 'active', 5, 24, 'This is KChat telling you about a feature. House ads fill space when no one else is advertising.'),
  ('KChat', 'https://api.kiongozi.org/ads-media/kchat-icon.png', 'Ask anything. In Sheng too.', 'Ask Kiongozi AI anything: homework, money, jobs, news. English, Kiswahili or Sheng.', 'https://api.kiongozi.org/ads-media/ad_ai.jpg', 'image', 1080, 1350, 'data:image/jpeg;base64,', 'Ask Kiongozi AI', 'kchat://ai', true, 'active', 5, 24, 'This is KChat telling you about a feature. House ads fill space when no one else is advertising.'),
  ('KChat', 'https://api.kiongozi.org/ads-media/kchat-icon.png', 'Your week, painted.', 'Every week KChat paints a recap of your posts, likes and new followers. Share it to your story.', 'https://api.kiongozi.org/ads-media/ad_week.jpg', 'image', 1080, 1350, 'data:image/jpeg;base64,', 'See your week', 'kchat://recap', true, 'active', 5, 24, 'This is KChat telling you about a feature. House ads fill space when no one else is advertising.'),
  ('KChat', 'https://api.kiongozi.org/ads-media/kchat-icon.png', 'Post it before it’s gone.', 'Stories disappear after 24 hours. Post the moment, not the perfect one.', 'https://api.kiongozi.org/ads-media/ad_story.jpg', 'image', 1080, 1350, 'data:image/jpeg;base64,', 'Add a story', 'kchat://story', true, 'active', 5, 24, 'This is KChat telling you about a feature. House ads fill space when no one else is advertising.')
) as v
where not exists (select 1 from public.ad_campaigns where is_house);
